import React, { useState, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import StaffDashboard from './components/StaffDashboard';

const supabase = createClient(
    'https://ixikhufrylaugpdxokwu.supabase.co',
    'sb_publishable_7T38wLjTEs7UJKMMTxl9tQ_OLM6Wsf3'
);

function App() {
    const [loading, setLoading] = useState(true);
    const [staffInfo, setStaffInfo] = useState(null);
    const [error, setError] = useState(null);
    
    useEffect(() => {
        // Get the currently logged-in user from Supabase Auth
        const getUserAndStaffInfo = async () => {
            try {
                // Get current session
                const { data: { session }, error: sessionError } = await supabase.auth.getSession();
                
                if (sessionError) {
                    console.error('Session error:', sessionError);
                    setError('Failed to get session');
                    setLoading(false);
                    return;
                }
                
                if (!session) {
                    // No user logged in - show login button
                    setError('not_authenticated');
                    setLoading(false);
                    return;
                }
                
                const user = session.user;
                console.log('Logged in user:', user.email);
                
                // First, try to find staff in the Staff table by email
                let { data: staffData, error: staffError } = await supabase
                    .from('Staff')
                    .select('*')
                    .eq('email', user.email)
                    .single();
                
                // If not found by email, try by id match
                if (staffError || !staffData) {
                    console.log('Staff not found by email, trying by id...');
                    const { data: staffById, error: idError } = await supabase
                        .from('Staff')
                        .select('*')
                        .eq('id', user.id)
                        .single();
                    
                    if (!idError && staffById) {
                        staffData = staffById;
                    }
                }
                
                if (staffData) {
                    console.log('Staff found:', staffData);
                    setStaffInfo({
                        clinicId: staffData.ClinicID,
                        staffId: staffData.id,
                        staffName: staffData.full_name,
                        email: staffData.email,
                        occupation: staffData.Occupation
                    });
                } else {
                    // No staff record found - check if user is in users table
                    const { data: userData, error: userError } = await supabase
                        .from('users')
                        .select('*')
                        .eq('email', user.email)
                        .single();
                    
                    if (userData && userData.role === 'staff') {
                        // User exists but no staff record - create one
                        const { data: newStaff, error: createError } = await supabase
                            .from('Staff')
                            .insert({
                                id: user.id,
                                full_name: user.user_metadata?.full_name || user.email,
                                email: user.email,
                                ClinicID: 'clinic_001', // Default clinic
                                Occupation: 'Medical Staff',
                                contact: user.user_metadata?.phone || ''
                            })
                            .select()
                            .single();
                        
                        if (!createError && newStaff) {
                            setStaffInfo({
                                clinicId: newStaff.ClinicID,
                                staffId: newStaff.id,
                                staffName: newStaff.full_name,
                                email: newStaff.email
                            });
                        } else {
                            setError('Staff record could not be created');
                        }
                    } else {
                        // User is not staff
                        setError('not_staff');
                    }
                }
                
                setLoading(false);
            } catch (err) {
                console.error('Error:', err);
                setError(err.message);
                setLoading(false);
            }
        };
        
        getUserAndStaffInfo();
        
        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
            if (event === 'SIGNED_IN' && session) {
                getUserAndStaffInfo();
            } else if (event === 'SIGNED_OUT') {
                setStaffInfo(null);
                setError('not_authenticated');
            }
        });
        
        return () => subscription.unsubscribe();
    }, []);
    
    const handleLogin = async () => {
        try {
            const { error } = await supabase.auth.signInWithOAuth({
                provider: 'google',
                options: {
                    redirectTo: window.location.origin
                }
            });
            if (error) throw error;
        } catch (err) {
            console.error('Login error:', err);
            alert('Login failed: ' + err.message);
        }
    };
    
    const handleLogout = async () => {
        await supabase.auth.signOut();
        setStaffInfo(null);
        setError('not_authenticated');
    };
    
    if (loading) {
        return (
            <div style={{ padding: '40px', textAlign: 'center' }}>
                <h2>Loading...</h2>
                <p>Connecting to your account...</p>
            </div>
        );
    }
    
    if (error === 'not_authenticated' || !staffInfo) {
        return (
            <div style={{ 
                display: 'flex', 
                justifyContent: 'center', 
                alignItems: 'center', 
                height: '100vh',
                fontFamily: 'Arial, sans-serif'
            }}>
                <div style={{ textAlign: 'center', padding: '40px', maxWidth: '400px' }}>
                    <div style={{ fontSize: '64px', marginBottom: '20px' }}>🏥</div>
                    <h1>Clinic Queue Management System</h1>
                    <p style={{ color: '#666', marginBottom: '30px' }}>
                        Please log in with your staff Google account to access the dashboard.
                    </p>
                    <button 
                        onClick={handleLogin}
                        style={{
                            background: '#6366f1',
                            color: 'white',
                            border: 'none',
                            padding: '12px 24px',
                            borderRadius: '8px',
                            fontSize: '16px',
                            cursor: 'pointer',
                            fontWeight: 'bold'
                        }}
                    >
                        🔐 Login with Google
                    </button>
                </div>
            </div>
        );
    }
    
    if (error === 'not_staff') {
        return (
            <div style={{ padding: '40px', textAlign: 'center', color: 'red' }}>
                <h2>Access Denied</h2>
                <p>Your account does not have staff privileges.</p>
                <p>Please contact the administrator.</p>
                <button 
                    onClick={handleLogout}
                    style={{
                        background: '#6b7280',
                        color: 'white',
                        border: 'none',
                        padding: '10px 20px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        marginTop: '20px'
                    }}
                >
                    Logout
                </button>
            </div>
        );
    }
    
    if (error) {
        return (
            <div style={{ padding: '40px', textAlign: 'center', color: 'red' }}>
                <h2>Error</h2>
                <p>{error}</p>
                <button 
                    onClick={() => window.location.reload()}
                    style={{
                        background: '#6366f1',
                        color: 'white',
                        border: 'none',
                        padding: '10px 20px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        marginTop: '20px'
                    }}
                >
                    Retry
                </button>
            </div>
        );
    }
    
    return (
        <StaffDashboard 
            clinicId={staffInfo.clinicId}
            staffId={staffInfo.staffId}
            staffName={staffInfo.staffName}
        />
    );
}

export default App;
